const obj=v=>v&&typeof v==='object'&&!Array.isArray(v),num=v=>typeof v==='number'&&Number.isFinite(v);
const auto=c.automatic,presenterAuto=Array.isArray(auto._presenter);
const top=['decision_report','scene_order','scenes',...(presenterAuto?['presenter']:[])].sort().join(',');
if(!obj(d)||Object.keys(d).sort().join(',')!==top)bad('campos');
const byId=new Map(q.scenes.map(s=>[s.id,s])),order=d.scene_order;
