if(c.scene_order==='manual'&&JSON.stringify(order)!==JSON.stringify(q.scenes.map(s=>s.id)))bad('a ordem é do usuário');
const field={duration:'duration_seconds',source_start:'source_start_seconds',transition_after:'transition',orientation:'pose',fit:'fit',framing:'crop'};
// The director only describes the posture it sees; the clockwise rotation is derived here, never by the model
// (real case intake 974643: "deitada para a esquerda" described right, 270 chosen instead of 90).
