 // Images have no source time: a template start of 0 copied into an image decision carries no choice and is dropped.
 if(byId.get(item.id).kind==='image'&&item.source_start_seconds===0){delete item.source_start_seconds;}
 const expected=auto[item.id].map(f=>field[f]).sort().join(',');
 if(Object.keys(item).filter(k=>k!=='id').sort().join(',')!==expected)bad(item.id+': decida exatamente '+expected);
