 if('pose'in item){if(!Object.hasOwn(POSES,item.pose))bad(item.id+': pose upright, head_left, head_right, inverted ou unclear');delete out.pose;out.rotation=POSES[item.pose];}
 if('fit'in item&&!FITS.includes(item.fit))bad(item.id+': fit contain, cover ou blur_background');
