}
const pending=Object.keys(auto).filter(id=>!['_order','_presenter'].includes(id)&&!decided.has(id));
if(pending.length)bad('faltam decisões: '+pending.join(', '));
if(presenterAuto&&(!obj(d.presenter)||Object.keys(d.presenter).join(',')!=='pose'||!Object.hasOwn(POSES,d.presenter.pose)))bad('apresentador: somente pose upright, head_left, head_right, inverted ou unclear');
const presenterRotation=presenterAuto?POSES[d.presenter.pose]:null;
