let total=0;
for(const [i,id]of order.entries()){
 const s=byId.get(id),dur=value(s,'duration_seconds',s.duration.seconds);
 if(!num(dur)||dur<c.min_scene_seconds||dur>c.max_scene_seconds)bad(id+': duração fora dos limites');
 // A scene of the main video under its own voice has no start of its own: it follows the chosen speech.
 if(s.kind==='video'&&!s.loop){const start=value(s,'source_start_seconds',s.source_start?.mode==='manual'?s.source_start.seconds:null);if(start!==null&&(!num(start)||start<0||start+dur>s.material_seconds+1e-6))bad(id+': trecho passa do fim do vídeo');}
