const previews=[];
for(const id of order){
 if(!visual(id))continue;
 const s=byId.get(id),it=decided.get(id)??{},out=scenes.find(x=>x.id===id)??{};
 const rotation='rotation'in out?out.rotation:(s.orientation?.rotation??0),fit='fit'in it?it.fit:s.fit;
 const crop='crop'in out?out.crop:(s.framing?.mode==='manual'?s.framing.crop:null);
