 previews.push({id,asset_id:s.material,fit,rotation,...(crop?{crop}:{}),...(s.kind==='video'?{time:Math.round((start+Math.min(1,dur/2))*100)/100}:{})});
}
if(presenterAuto)previews.push({id:'_presenter',asset_id:c.presenter.material,fit:c.presenter.fit,rotation:presenterRotation,time:Math.round(Math.min(5,c.presenter.material_seconds/2)*100)/100});
const direction={kind:'scene_direction',request_sha256:q.request_sha256,scene_order:order,scenes,decision_report:report,...(presenterAuto?{presenter:{rotation:presenterRotation}}:{})};
return [{json:{status:'ready',kind:'scene_direction',operation_id:prepared.operation_id,windmill_job_id:prepared.windmill_job_id,windmill_job_url:prepared.windmill_job_url,
 content_seconds:Math.round(total*1000)/1000,direction,needs_preview:previews.length>0,
 preview_payload:{sources:request.payload.sources,canvas:{width:c.canvas.width,height:c.canvas.height},scenes:previews}}}];

// "Fixar job da prévia": the scene_preview job UUID; polled, never resubmitted.
const raw=$input.first().json.job_id;
const id=typeof raw==='string'?raw.trim().replace(/^"|"$/g,''):'';
if(!/^[0-9a-f-]{36}$/i.test(id))throw new Error('SCENE_PREVIEW_JOB_INVALID: Windmill não devolveu o UUID do job');
return [{json:{preview_job_id:id,preview_job_url:'https://wll.miabuilder.com/run/'+id+'?workspace=mia-micro-servicos'}}];

// "Avaliar prévia das cenas": one poll every 3 s (node "Aguardar prévia"); 120 polls = 6 min.
// Timeout never resubmits: P2 consults the same job URL.
const job=$input.first().json,ctx=$('Fixar job da prévia').first().json;
const completed=job.type==='CompletedJob'||job.completed_at!=null||typeof job.success==='boolean';
const attempt=$runIndex+1;
if(job.id!==ctx.preview_job_id||job.args?.action!=='scene_preview')throw new Error('SCENE_PREVIEW_JOB_MISMATCH: resposta de outro job');
// The engine's own code ([CODE] detail) reaches P2 first; generic code only when there is none (e.g. canceled).
const engine=/^\[([A-Z][A-Z0-9_]+)\]\s*([\s\S]*)$/.exec(String(job.result?.error?.message??''));
if(job.canceled||job.is_canceled||(completed&&job.success!==true))throw new Error(engine?engine[1]+': '+engine[2]+' '+ctx.preview_job_url:'SCENE_PREVIEW_FAILED: prévia falhou ou foi cancelada. '+ctx.preview_job_url);
if(!completed&&attempt>=120)throw new Error('SCENE_PREVIEW_TIMEOUT: não reenviar automaticamente; '+ctx.preview_job_url);
return [{json:{...ctx,attempt,completed}}];

// "Preparar conferência de cenas": the framed scenes (engine scene_preview) -> the second look's request.
// Up to four sheets of eight scenes; empty slots are a blank frame, never another scene.
const r=$input.first().json,validated=$('Validar direção de cenas').first().json,expected=validated.preview_payload.scenes;
const BLANK='data:image/jpeg;base64,/9j/4AAQSkZJRgABAgAAAQABAAD//gAQTGF2YzYwLjMxLjEwMgD/2wBDAAgUFBcUFxsbGxsbGyAeICEhISAgICAhISEkJCQqKiokJCQhISQkKCgqKi4vLisrKisvLzIyMjw8OTlGRkhWVmf/xABLAAEBAAAAAAAAAAAAAAAAAAAACAEBAAAAAAAAAAAAAAAAAAAAABABAAAAAAAAAAAAAAAAAAAAABEBAAAAAAAAAAAAAAAAAAAAAP/AABEIABAAEAMBIgACEQADEQD/2gAMAwEAAhEDEQA/AJ/AB//Z';
if(!r||r.kind!=='scene_preview'||!/^\d+\.\d+\.\d+$/.test(r.engine_version??'')||!Array.isArray(r.sheets)||!r.sheets.length||r.sheets.length>4)throw new Error('SCENE_PREVIEW_INVALID: prévia ausente');
if(r.sheets.some(s=>typeof s.image_url!=='string'||!s.image_url.startsWith('data:image/jpeg;base64,')||!Array.isArray(s.tiles)))throw new Error('SCENE_PREVIEW_INVALID: folha inválida');
const drawn=r.sheets.flatMap(s=>s.tiles.map(t=>t.scene_id));
if(JSON.stringify(drawn)!==JSON.stringify(expected.map(s=>s.id)))throw new Error('SCENE_PREVIEW_INVALID: cenas da prévia não correspondem à decisão');
const c=$('02 Validar preparo').first().json.scene_request.constraints;
const review_request={task:'scene_preview_review',canvas:c.canvas,
 // Only what to look at: the decision itself is withheld so the second look judges the picture, not the intent
 // (real case intake 974638: told "rotation 90", the reviewer refused scenes that were drawn upright).
 scenes:expected.map(s=>({id:s.id})),
 sheets:r.sheets.map((s,i)=>({image:i+1,scenes:s.tiles.map(t=>t.scene_id)})),empty_images:4-r.sheets.length};
const images=[...r.sheets.map(s=>s.image_url),...Array(4-r.sheets.length).fill(BLANK)];
return [{json:{review_request,images,preview_job_id:$('Fixar job da prévia').first().json.preview_job_id}}];

// "Aprovar direção de cenas": final intake result. With visual decisions, the second look must approve every
// framed scene (upright and well framed); a refusal stops here with its reasons, nothing is rendered.
const v=$('Validar direção de cenas').first().json;
let preview_review={approved:true,scenes:[],reason:'Sem decisão visual automática: nada a conferir.'};
if(v.needs_preview){
 const raw=$input.first().json,text=raw.output??raw.text??raw;
 let a;try{a=typeof text==='string'?JSON.parse(text.replace(/^\x60\x60\x60(?:json)?\s*/,'').replace(/\s*\x60\x60\x60$/,'')):text;}catch{throw new Error('SCENE_DIRECTION_REVIEW_INVALID: resposta não é JSON');}
 const obj=x=>x&&typeof x==='object'&&!Array.isArray(x),ids=v.preview_payload.scenes.map(s=>s.id);
 if(!obj(a)||Object.keys(a).sort().join(',')!=='approved,reason,scenes'||typeof a.approved!=='boolean'||typeof a.reason!=='string'||!a.reason.trim()||!Array.isArray(a.scenes))throw new Error('SCENE_DIRECTION_REVIEW_INVALID: campos');
 if(JSON.stringify(a.scenes.map(s=>s?.id))!==JSON.stringify(ids)||a.scenes.some(s=>!obj(s)||Object.keys(s).sort().join(',')!=='framing_ok,id,reason,upright'||typeof s.upright!=='boolean'||typeof s.framing_ok!=='boolean'||typeof s.reason!=='string'||!s.reason.trim()))throw new Error('SCENE_DIRECTION_REVIEW_INVALID: uma conferência por cena, na ordem');
 const failed=a.scenes.filter(s=>!s.upright||!s.framing_ok);
 if(failed.length||!a.approved)throw new Error('SCENE_DIRECTION_REVIEW_REQUIRED: '+(failed.length?failed.map(s=>s.id+' — '+s.reason).join(' | '):a.reason));
 preview_review={approved:true,scenes:a.scenes,reason:a.reason.trim(),preview_job_id:$('Preparar conferência de cenas').first().json.preview_job_id};
}
const {needs_preview,preview_payload,...result}=v;
return [{json:{...result,direction:{...v.direction,preview_review}}}];
